local BaseEffect = import('Game.Chapter.NewChapterEffect.BaseEffect')
local base = BaseEffect
local ResourceModule = CS.Engine.Modules.ResourceModule
local cs_coroutine = require 'XLua.cs_coroutine'
local Yielders = CS.Engine.Lib.Yielders
local KTool = CS.Engine.Lib.KTool

---全屏警告特效
---@class SceneWarningEffect : BaseEffect
local SceneWarningEffect = Class("SceneWarningEffect", BaseEffect)

local NewChapterConstants = import('Game.Chapter.NewChapterConstants')

function SceneWarningEffect:__init()
    self._isFinish = nil
    self._loadedRes = nil
    self._co = nil
end

function SceneWarningEffect:__delete()
    self._isFinish = nil
    self._loadedRes = nil
    self._co = nil
end

function SceneWarningEffect:Initialize(parameters)
    base.StartEffect(self, parameters)
end

function SceneWarningEffect:StartEffect(object)
    base.StartEffect(self, object)
    self.isFinish = false
    if not isNull(self._loadedRes) then
        self.isFinish = true
        return
    end
    self.co = cs_coroutine.start(function()
        local loader = ResourceModule.LoadBundleAsync(NewChapterConstants.SceneWarningPath, nil, true)
        while not loader.IsCompleted do
            coroutine.yield(Yielders.EndOfFrame)
        end

        if loader.IsSuccess then

            local modelIns = loader:Instantiate()
            KTool.ChangeAllLayer(modelIns, 17, 0)

            modelIns.transform:SetParent(object.transform)
            modelIns.transform.localPosition = Vector3.New(0,0,0.15)
            modelIns.transform.localScale = Vector3.New(2.2,1.6,1)
            modelIns.transform.localRotation = CS.UnityEngine.Quaternion.identity
            self._loadedRes = modelIns

            KTool.SetActive(modelIns.gameObject, true)


            self.loader = loader
        else
            loader:Release()
        end


        self.isFinish = true
        self.co = nil

    end)
end

function SceneWarningEffect:IsFinish()
    base.IsFinish(self)
    return self.isFinish
end

function SceneWarningEffect:EndEffect(object)
    base.EndEffect(self, object)
end

function SceneWarningEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)
    KTool.SafeDelete(self._loadedRes)
    if not isNull(self.loader) then
        self.loader:Release()
    end
end

return SceneWarningEffect